#version 330
// The book's surface: printed cloth with a pressed relief, metal-leaf foil,
// lacquer gloss and glitter, lit by the scene's ambient, two directional and
// one spot light.
//
// Inputs (all painted or generated by this project): the cover atlas
// (textures.ts) for print, pressed relief, foil and gloss masks, and the
// generated shading overlay, cloth relief and glitter tile (press_book.c).
// The Blinn-Phong lighting functions are ported from three.js shader chunks
// (MIT licence); the relief normal follows M. Mikkelsen, "Bump Mapping
// Unparametrized Surfaces on the GPU" (2010).
in vec2 vUv;
in vec3 vViewPosition;
in vec3 vNormal;
out vec4 fragColor;

uniform sampler2D diffuseMapBase;    // shading overlay, 0.5 neutral
uniform sampler2D diffuseMapCustom;  // the cover atlas: print and the foil tile
uniform sampler2D bumpMapBase;       // cloth or paper relief
uniform sampler2D bumpMapCustom;     // the cover's pressed artwork
uniform sampler2D foilMap;
uniform sampler2D glossMap;
uniform sampler2D glitterMap;

uniform vec3 specular;
uniform float shininess;
uniform float reflectiveness;
uniform vec3 diffuseBaseColor;  // the darkest tone the foil leaf takes
uniform float bumpScaleBase;
uniform float bumpScaleCustom;
uniform float foilDetail;
uniform float foilOpacity;
uniform float foilSpecular;
uniform float foilEmissive;
uniform float glossOpacity;
uniform float glossSpecular;
uniform float glossEmissive;
uniform float glitterOpacity;
uniform float glitterSpecular;
uniform float glitterEmissive;

uniform vec3 ambientLightColor;
uniform vec3 directionalDirection[2];
uniform vec3 directionalColor[2];
uniform vec3 spotPosition;
uniform vec3 spotDirection;
uniform vec3 spotColor;
uniform float spotConeCos;
uniform float spotPenumbraCos;

#define saturate(a) clamp(a, 0.0, 1.0)
#define RECIPROCAL_PI 0.3183098861837907

// ── lighting (three.js Blinn-Phong, MIT) ────────────────────────────────────
vec3 F_Schlick(vec3 f0, float f90, float dotVH) {
  float fresnel = exp2((-5.55473 * dotVH - 6.98316) * dotVH);
  return f0 * (1.0 - fresnel) + (f90 * fresnel);
}
vec3 BRDF_BlinnPhong(vec3 lightDir, vec3 viewDir, vec3 normal, vec3 specularColor, float exponent) {
  vec3 halfDir = normalize(lightDir + viewDir);
  float dotNH = saturate(dot(normal, halfDir));
  float dotVH = saturate(dot(viewDir, halfDir));
  vec3 F = F_Schlick(specularColor, 1.0, dotVH);
  float D = RECIPROCAL_PI * (exponent * 0.5 + 1.0) * pow(dotNH, exponent);
  return F * (0.25 * D);
}

// ── the surface ─────────────────────────────────────────────────────────────

// Relief height: the shared cloth relief (which foil and lacquer fill in) plus
// the cover's own pressed artwork.
float relief(vec2 uv) {
  float filled = saturate(saturate(texture(foilMap, uv).r * foilOpacity) + texture(glossMap, uv).r * glossOpacity);
  float cloth = (texture(bumpMapBase, uv).r - 0.5) * bumpScaleBase * (1.0 - filled);
  float pressed = (texture(bumpMapCustom, uv).r - 0.5) * bumpScaleCustom;
  return cloth + pressed;
}

// Tilt the normal by the relief's screen-space slope (Mikkelsen 2010).
vec3 reliefNormal(vec3 normal) {
  vec3 position = -vViewPosition;
  vec3 dpx = dFdx(position), dpy = dFdy(position);
  vec3 r1 = cross(dpy, normal), r2 = cross(normal, dpx);
  float det = dot(dpx, r1);
  float h = relief(vUv);
  float dhx = relief(vUv + dFdx(vUv)) - h;
  float dhy = relief(vUv + dFdy(vUv)) - h;
  vec3 slope = sign(det) * (dhx * r1 + dhy * r2);
  return normalize(abs(det) * normal - slope);
}

float hash(vec2 p) { return fract(sin(dot(p, vec2(41.3, 289.1))) * 15731.743); }

struct Surface { vec3 albedo; vec3 specularColor; float strength; float exponent; };

void addLight(vec3 lightDir, vec3 color, vec3 normal, vec3 viewDir, Surface s, inout vec3 diffuse, inout vec3 shine) {
  float dotNL = saturate(dot(normal, lightDir));
  vec3 irradiance = dotNL * color;
  diffuse += irradiance * RECIPROCAL_PI * s.albedo;
  shine += irradiance * BRDF_BlinnPhong(lightDir, viewDir, normal, s.specularColor, s.exponent) * s.strength;
}

void main() {
  vec3 normal = reliefNormal(normalize(vNormal));
  vec3 viewDir = normalize(vViewPosition);
  float facing = saturate(dot(normal, viewDir));

  // Print on cloth, shaded by the overlay (0.5 leaves it as printed).
  vec3 print = texture(diffuseMapCustom, vUv).rgb;
  float shade = texture(diffuseMapBase, vUv).r;
  vec3 albedo = print * shade * 2.0;

  // Foil: metal leaf. It mirrors its surroundings, and the two-tone tile
  // textures.ts paints in the atlas's top-left corner stands in for them:
  // the reflected view direction picks the point of the tile, so the leaf
  // shifts between its tones across the cover and as the book turns.
  float foil = saturate(texture(foilMap, vUv).r * foilOpacity);  // no leaf below zero
  vec3 mirrored = reflect(-viewDir, normal);
  vec2 sweep = 0.5 * sin(mirrored.xy * (2.0 + 4.0 * foilDetail));
  vec3 leaf = max(texture(diffuseMapCustom, vec2(0.07, 0.905) + sweep * vec2(0.12, 0.17)).rgb, diffuseBaseColor);
  albedo = mix(albedo, leaf * 0.6, foil);  // its tone comes mostly from the tile

  // Lacquer: smoother, brighter highlights and a sheen at grazing angles.
  float gloss = texture(glossMap, vUv).r * glossOpacity;

  // Glitter: small flakes, each tilted its own way, that flash when one
  // catches a light.
  vec2 flakeCell = floor(vUv * 3000.0);
  float flake = texture(glitterMap, fract(vUv * 30.0)).r;
  float glitter = glitterOpacity * smoothstep(0.7, 0.9, flake);
  vec3 jitter = vec3(hash(flakeCell), hash(flakeCell + 17.0), hash(flakeCell + 43.0)) - 0.5;
  vec3 flakeNormal = normalize(normal + jitter * 0.9);

  Surface s;
  s.albedo = albedo;
  s.specularColor = mix(specular, leaf, foil);
  s.strength = mix(reflectiveness, max(0.3 + foilSpecular, 0.0), foil) + gloss * glossSpecular * 4.0;
  s.exponent = shininess * (1.0 + gloss * 40.0) + foil * 30.0;

  vec3 diffuse = ambientLightColor * RECIPROCAL_PI * albedo;
  vec3 shine = vec3(0.0);
  vec3 sparkle = vec3(0.0);
  for (int i = 0; i < 2; i++) {
    addLight(directionalDirection[i], directionalColor[i], normal, viewDir, s, diffuse, shine);
    sparkle += directionalColor[i] * pow(saturate(dot(reflect(-directionalDirection[i], flakeNormal), viewDir)), 90.0);
  }
  vec3 toSpot = normalize(spotPosition + vViewPosition);
  float cone = smoothstep(spotConeCos, spotPenumbraCos, dot(toSpot, spotDirection));
  if (cone > 0.0) {
    addLight(toSpot, spotColor * cone, normal, viewDir, s, diffuse, shine);
    sparkle += spotColor * cone * pow(saturate(dot(reflect(-toSpot, flakeNormal), viewDir)), 90.0);
  }

  vec3 color = diffuse + shine;
  color += leaf * foil * foilEmissive * 0.3;                        // leaf catches the room
  color += vec3(gloss * (glossEmissive + 0.06) * pow(1.0 - facing, 3.0));  // lacquer sheen
  color += sparkle * glitter * (0.3 + glitterSpecular) * (1.0 + glitterEmissive);
  fragColor = vec4(color, 1.0);
}
